const r=[{text:"إِنَّ مَعَ الْعُسْرِ يُسْرًا",surah:"الشرح",number:6,tafsir:"إن مع الضيق والشدة فرجاً ومخرجاً، فاصبر واحتسب فإن الله مع الصابرين."},{text:"وَقُل رَّبِّ زِدْنِي عِلْمًا",surah:"طه",number:114,tafsir:"وقل يا محمد: رب زدني علماً إلى ما علمتني، فالعلم هو النور الذي يهتدي به الإنسان."},{text:"فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ",surah:"البقرة",number:152,tafsir:"اذكروني بطاعتي أذكركم بمغفرتي وثوابي، واشكروا لي نعمي ولا تجحدوها."},{text:"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ",surah:"البقرة",number:186,tafsir:"وإذا سألك عبادي عني فإني قريب منهم بعلمي وإجابتي، أجيب دعاء من دعاني إذا أخلص في دعائه."},{text:"لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا",surah:"البقرة",number:286,tafsir:"لا يوجب الله على نفس من الأعمال إلا ما تطيقه وتقدر عليه، رحمة منه وفضلاً."},{text:"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ",surah:"آل عمران",number:8,tafsir:"يا ربنا لا تمل قلوبنا عن الحق بعد أن هديتنا إليه، وأعطنا من فضلك رحمة واسعة، إنك أنت المعطي بلا حدود."},{text:"وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا",surah:"آل عمران",number:103,tafsir:"وتمسكوا جميعاً بدين الله وعهده، ولا تختلفوا فتتفرقوا وتضعفوا."},{text:"الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ اللَّهِ ۗ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ",surah:"الرعد",number:28,tafsir:"الذين صدقوا بآيات الله وتسكن قلوبهم وتأنس بذكر الله، ألا بذكر الله وحده تسكن القلوب وتزول مخاوفها."},{text:"وَقُل لِّعِبَادِي يَقُولُوا الَّتِي هِيَ أَحْسَنُ",surah:"الإسراء",number:53,tafsir:"وقل لعبادي المؤمنين يقولوا في تخاطبهم الكلمات الطيبة التي هي أحسن وأجمل."},{text:"وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ",surah:"الطلاق",number:2,tafsir:"ومن يخف الله فيعمل بطاعته، يجعل له مخرجاً من كل ضيق، ويرزقه من حيث لا يخطر على باله."},{text:"وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ",surah:"الطلاق",number:3,tafsir:"ومن يعتمد على الله ويفوض أمره إليه، فهو كافيه وميسر أمره."},{text:"ادْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ",surah:"النحل",number:125,tafsir:"ادع الناس إلى دين ربك بالطريقة الحكيمة والقول اللين والوعظ الجميل."},{text:"إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَّالَّذِينَ هُم مُّحْسِنُونَ",surah:"النحل",number:128,tafsir:"إن الله بعونه وتوفيقه مع الذين خافوه فاجتنبوا معاصيه، والذين هم محسنون في عبادتهم ومعاملتهم."},{text:"وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا",surah:"الطور",number:48,tafsir:"واصبر يا محمد على ما يلحقك من أذى قومك، فإنك تحت حفظنا ورعايتنا."},{text:"وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَىٰ",surah:"البقرة",number:197,tafsir:"وخذوا معكم ما يكفيكم من زاد لسفركم، واعلموا أن خير ما يتزود به الإنسان هو تقوى الله."},{text:"فَاصْبِرْ صَبْرًا جَمِيلًا",surah:"المعارج",number:5,tafsir:"فاصبر يا محمد على أذاهم صبراً لا شكوى فيه لغير الله."},{text:"أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ",surah:"الزمر",number:36,tafsir:"أليس الله بكافٍ عبده محمداً صلى الله عليه وسلم شر أعدائه؟ بلى هو كافيه وناصره."},{text:"وَأَحْسِنُوا ۛ إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ",surah:"البقرة",number:195,tafsir:"وأحسنوا في كل أعمالكم، فإن الله يحب الذين يحسنون في عبادتهم ومعاملاتهم."},{text:"إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ",surah:"هود",number:61,tafsir:"إن ربي قريب ممن أخلص له العبادة، مجيب لمن دعاه."},{text:"قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ",surah:"الزمر",number:53,tafsir:"قل يا محمد لعبادي الذين تجاوزوا الحد في الذنوب: لا تيأسوا من رحمة الله ومغفرته."},{text:"وَاللَّهُ يَعْلَمُ مَا فِي قُلُوبِكُمْ",surah:"الأحزاب",number:51,tafsir:"والله يعلم ما تكنه صدوركم من خير أو شر، وسيجازيكم عليه."},{text:"وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ",surah:"الحديد",number:4,tafsir:"وهو سبحانه معكم بعلمه واطلاعه أينما كنتم، لا يخفى عليه من أمركم شيء."},{text:"قُلِ اللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ",surah:"الأنعام",number:64,tafsir:"قل يا محمد: الله وحده هو الذي ينجيكم من هذه الشدائد ومن كل ضيق عظيم."},{text:"وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ",surah:"الأنبياء",number:83,tafsir:"واذكر أيوب حين دعا ربه قائلاً: يا رب لقد أصابني المرض والشدة، وأنت أرحم الراحمين بي."},{text:"لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا",surah:"التوبة",number:40,tafsir:"لا تحزن ولا تخف، فإن الله معنا بنصره وتأييده وحفظه."},{text:"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ",surah:"الضحى",number:5,tafsir:"ولسوف يعطيك ربك يا محمد من أنواع الإنعام في الآخرة، فترضى بذلك."},{text:"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ",surah:"الشرح",number:1,tafsir:"ألم نوسع لك يا محمد صدرك بما أودعنا فيه من الهدى والإيمان؟"},{text:"فَإِنَّ مَعَ الْعُسْرِ يُسْرًا",surah:"الشرح",number:5,tafsir:"فإن مع الضيق والشدة فرجاً ومخرجاً."},{text:"وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ",surah:"الفرقان",number:58,tafsir:"واعتمد في كل أمورك على الله الحي الذي لا يموت، وفوض أمرك إليه."},{text:"وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ",surah:"غافر",number:60,tafsir:"وقال ربكم: اعبدوني وحدي وادعوني أجب دعاءكم وأغفر لكم."},{text:"نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ",surah:"الحجر",number:49,tafsir:"أخبر عبادي يا محمد أني أنا الغفور لذنوب التائبين، الرحيم بهم."},{text:"وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ",surah:"الشعراء",number:80,tafsir:"وإذا أصابني مرض فهو وحده الذي يشفيني منه."},{text:"لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا",surah:"الطلاق",number:1,tafsir:"أنت لا تعلم ما سيحدث، فربما يغير الله الأحوال ويأتي بالفرج بعد الضيق."},{text:"وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهو خَيْرٌ لَّكُمْ",surah:"البقرة",number:216,tafsir:"وربما تكرهون شيئاً وهو في الحقيقة خير لكم في دنياكم وآخرتكم."},{text:"فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ",surah:"الروم",number:60,tafsir:"فاصبر يا محمد على أذى قومك، إن ما وعدك الله به من النصر والتمكين هو الحق الذي لا شك فيه."},{text:"إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ",surah:"آل عمران",number:159,tafsir:"إن الله يحب الذين يعتمدون عليه ويفوضون أمورهم إليه."},{text:"وَمَا كَانَ رَبُّكَ نَسِيًّا",surah:"مريم",number:64,tafsir:"وما كان ربك يا محمد ناسياً لك ولا لأي شيء من خلقه، بل هو عليم بكل شيء."},{text:"قَالَ لَا تَخَافَا ۖ إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَىٰ",surah:"طه",number:46,tafsir:"قال الله لموسى وهارون: لا تخافا من فرعون، إنني معكما بحفظي ونصري، أسمع قولكما وأرى فعلكما."},{text:"وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ",surah:"هود",number:88,tafsir:"وما أصيبه من الحق والسداد في أموري إلا بتوفيق الله ومعونته."},{text:"إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ",surah:"الأعراف",number:56,tafsir:"إن رحمة الله وإحسانه قريب من الذين يحسنون في عبادتهم ومعاملاتهم."},{text:"وَاللَّهُ مَعَ الصَّابِرِينَ",surah:"البقرة",number:249,tafsir:"والله مع الصابرين بنصره وتأييده وحفظه."},{text:"فَاللَّهُ خَيْرٌ حَافِظًا ۖ وَهُوَ أَرْحَمُ الرَّاحِمِينَ",surah:"يوسف",number:64,tafsir:"فالله خير من يحفظ، وهو أرحم الراحمين بعباده."},{text:"وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ",surah:"غافر",number:44,tafsir:"وأسلم أمري إلى الله وأتوكل عليه، فهو كافيني."},{text:"رَبِّ اشْرَحْ لِي صَدْرِي",surah:"طه",number:25,tafsir:"قال موسى: رب وسع لي صدري بما يسهل علي القيام بأمرك."},{text:"وَيَسِّرْ لِي أَمْرِي",surah:"طه",number:26,tafsir:"وسهل علي القيام بما كلفتني به من الرسالة."},{text:"إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ",surah:"البقرة",number:20,tafsir:"إن الله لا يعجزه شيء في الأرض ولا في السماء، وهو قادر على كل شيء."},{text:"يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ",surah:"البقرة",number:185,tafsir:"يريد الله بشرعه هذا السهولة واليسر، ولا يريد بكم المشقة والضيق."},{text:"إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا",surah:"الحج",number:38,tafsir:"إن الله يدفع عن المؤمنين شر أعدائهم ويحفظهم."},{text:"وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ",surah:"الروم",number:47,tafsir:"وكان واجباً علينا بفضلنا نصر المؤمنين على أعدائهم."},{text:"إِنَّ اللَّهَ يَجْزِي الْمُتَصَدِّقِينَ",surah:"يوسف",number:88,tafsir:"إن الله يثيب الذين يتصدقون بأموالهم ويجازيهم أحسن الجزاء."},{text:"وَاللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا",surah:"البقرة",number:268,tafsir:"والله يعدكم على إنفاقكم مغفرة لذنوبكم ورزقاً واسعاً."},{text:"إِنَّ اللَّهَ وَاسِعٌ عَلِيمٌ",surah:"البقرة",number:115,tafsir:"إن الله واسع الفضل والرحمة، عليم بكل شيء من أحوال خلقه."},{text:"وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِن شَيْءٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ",surah:"فاطر",number:44,tafsir:"وما كان الله ليفوته شيء أو يغلبه في السماوات ولا في الأرض."},{text:"إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَن يَقُولَ لَهُ كُن فَيَكُونُ",surah:"يس",number:82,tafsir:"إنما شأنه سبحانه إذا أراد إيجاد شيء أن يقول له: (كن)، فيكون ذلك الشيء فوراً."},{text:"وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ",surah:"يوسف",number:21,tafsir:"والله غالب على كل شأن من شؤونه، لا يغلبه أحد، ولا يمتنع عليه شيء."},{text:"إِنَّ رَبِّي لَطِيفٌ لِّمَا يَشَاءُ",surah:"يوسف",number:100,tafsir:"إن ربي لطيف في تدبيره، يوصل بره وإحسانه إلى عباده من حيث لا يشعرون."},{text:"وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ",surah:"البقرة",number:143,tafsir:"وما كان الله ليضيع صلاتكم وثواب أعمالكم."},{text:"وَاللَّهُ يُحِبُّ الصَّابِرِينَ",surah:"آل عمران",number:146,tafsir:"والله يحب الذين يصبرون على البلاء والشدائد في سبيله."},{text:"إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ",surah:"الإسراء",number:9,tafsir:"إن هذا القرآن الذي أنزلناه يرشد الناس إلى الطريق التي هي أعدل وأصوب."},{text:"وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ",surah:"الإسراء",number:82,tafsir:"وننزل من آيات القرآن ما يشفي القلوب من الأمراض، ويكون رحمة للمؤمنين."},{text:"وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ",surah:"النحل",number:127,tafsir:"واصبر يا محمد على ما يلحقك من أذى، وما صبرك إلا بتوفيق الله ومعونته."},{text:"إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ",surah:"التوبة",number:120,tafsir:"إن الله لا يضيع ثواب من أحسن عملاً وأخلص نيته."},{text:"وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْرًا",surah:"الطلاق",number:4,tafsir:"ومن يخف الله فيعمل بطاعته، يسهل له أموره وييسرها."},{text:"وَكَانَ فَضْلُ اللَّهِ عَلَيْكَ عَظِيمًا",surah:"النساء",number:113,tafsir:"وكان فضل الله وإحسانه إليك يا محمد عظيماً في كل شؤونك."},{text:"إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ",surah:"آل عمران",number:9,tafsir:"إن الله لا يخلف ما وعد به عباده من الثواب والعقاب."},{text:"وَمَا ذَٰلِكَ عَلَى اللَّهِ بِعَزِيزٍ",surah:"إبراهيم",number:20,tafsir:"وليس إهلاككم والإتيان بخلق جديد بصعب ولا ممتنع على الله."},{text:"وَاللَّهُ ذُو فَضْلٍ عَظِيمٍ",surah:"آل عمران",number:74,tafsir:"والله صاحب الفضل الواسع والعطاء العظيم على خلقه."},{text:"إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ",surah:"البقرة",number:243,tafsir:"إن الله لصاحب فضل عظيم على الناس بنعمه الكثيرة."},{text:"إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ",surah:"يوسف",number:100,tafsir:"إنه سبحانه هو العليم بأحوال خلقه، الحكيم في تدبيره وصنعه."},{text:"فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ",surah:"الأحقاف",number:35,tafsir:"فاصبر يا محمد على أذى قومك كما صبر الرسل الذين كانوا ذوي حزم وعزم."},{text:"وَمَا رَبُّكَ بِظَلَّامٍ لِّلْعَبِيدِ",surah:"فصلت",number:46,tafsir:"وما ربك بظالم لأحد من خلقه، بل يجازي كل إنسان بما عمل."},{text:"إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ",surah:"النساء",number:40,tafsir:"إن الله لا ينقص أحداً من ثواب عمله شيئاً، ولو كان قليلاً جداً."},{text:"وَإِن تَكُ حَسَنَةً يُضَاعِفْهَا",surah:"النساء",number:40,tafsir:"وإن تكن الفعلة حسنة يضاعف الله ثوابها لصاحبها."},{text:"فَأَمَّا مَن أَعْطَىٰ وَاتَّقَىٰ وَصَدَّقَ بِالْحُسْنَىٰ فَسَنُيَسِّرُهُ لِلْيُسْرَىٰ",surah:"الليل",number:5,tafsir:"فأما من بذل ماله واتقى ربه وصدق بالجنة، فسنوفقه للطريق الموصلة لكل خير."},{text:"قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَٰلِكَ فَلْيَفْرَحُوا",surah:"يونس",number:58,tafsir:"قل يا محمد: بفضل الله وهو الإسلام، وبرحمته وهو القرآن، فليفرح المؤمنون."},{text:"أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ",surah:"يونس",number:62,tafsir:"ألا إن أحباب الله المتقين لا خوف عليهم في الآخرة ولا هم يحزنون على ما فاتهم في الدنيا."},{text:"لَهُمُ الْبُشْرَىٰ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ",surah:"يونس",number:64,tafsir:"لهم البشارة الطيبة في الدنيا بالثناء الحسن والرؤيا الصالحة، وفي الآخرة بالجنة."},{text:"ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ",surah:"يونس",number:64,tafsir:"ذلك الذي ناله هؤلاء الأولياء هو الفلاح والنجاح العظيم."},{text:"وَاللَّهُ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ",surah:"البقرة",number:213,tafsir:"والله يوفق من يشاء من خلقه إلى الطريق المستقيم الموصل إلى جنته."},{text:"إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ",surah:"التوبة",number:111,tafsir:"إن الله قد وعد المؤمنين بالجنة مقابل بذل أنفسهم وأموالهم في سبيله."},{text:"وَبَشِّرِ الصَّابِرِينَ",surah:"البقرة",number:155,tafsir:"وأخبر الصابرين بما يسرهم من حسن الثواب في الدنيا والآخرة."},{text:"الَّذِينَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",surah:"البقرة",number:156,tafsir:"الذين إذا نزل بهم مكروه قالوا: نحن عبيد الله ملكاً وتدبيراً، وإليه مصيرنا."},{text:"أُولَٰئِكَ عَلَيْهِمْ صَلَوَاتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ",surah:"البقرة",number:157,tafsir:"أولئك الصابرون لهم ثناء من ربهم ورحمة واسعة."},{text:"وَأُولَٰئِكَ هُمُ الْمُهْتَدُونَ",surah:"البقرة",number:157,tafsir:"وأولئك هم الذين وفقهم الله لطريق الحق والهدى."},{text:"وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ",surah:"البقرة",number:216,tafsir:"والله يعلم ما هو خير لكم في عاقبة أمركم، وأنتم لا تعلمون ذلك."},{text:"إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ",surah:"هود",number:61,tafsir:"إن ربي قريب ممن أخلص له العبادة، مجيب لمن دعاه."},{text:"وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ",surah:"المائدة",number:120,tafsir:"وهو سبحانه على كل شيء قدير، لا يعجزه شيء في الأرض ولا في السماء."},{text:"إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ",surah:"غافر",number:44,tafsir:"إن الله مطلع على أحوال عباده، وسيجازيهم على أعمالهم."},{text:"وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ",surah:"البقرة",number:265,tafsir:"والله مطلع على كل ما تعملونه من خير أو شر، لا يخفى عليه شيء."},{text:"إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا",surah:"النساء",number:1,tafsir:"إن الله كان عليكم مراقباً لكل أحوالكم وأعمالكم."},{text:"وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقْتَدِرًا",surah:"الكهف",number:45,tafsir:"وكان الله على كل شيء مقتدراً، لا يمتنع عليه شيء أراده."},{text:"إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ",surah:"المائدة",number:42,tafsir:"إن الله يحب العادلين في أحكامهم وأفعالهم."},{text:"وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ",surah:"آل عمران",number:134,tafsir:"والله يحب الذين يحسنون في عبادتهم ومعاملتهم لخلقه."},{text:"إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ",surah:"البقرة",number:222,tafsir:"إن الله يحب الراجعين إليه من ذنوبهم، ويحب المتنزهين عن الأقذار."},{text:"وَاللَّهُ وَلِيُّ الْمُؤْمِنِينَ",surah:"آل عمران",number:68,tafsir:"والله ناصر المؤمنين ومعينهم وموفقهم."},{text:"إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَّالَّذِينَ هُم مُّحْسِنُونَ",surah:"النحل",number:128,tafsir:"إن الله مع الذين خافوه فاجتنبوا معاصيه، والذين هم محسنون في أعمالهم."},{text:"وَاللَّهُ يَدْعُو إِلَىٰ دَارِ السَّلَامِ",surah:"يونس",number:25,tafsir:"والله يدعو خلقه إلى الجنة التي يسلم فيها من كل آفة."},{text:"إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا",surah:"الكهف",number:30,tafsir:"إن الله لا ينقص ثواب من أحسن عملاً وأتقنه."},{text:"وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا",surah:"الطور",number:48,tafsir:"واصبر يا محمد لقضاء ربك، فإنك تحت حمايتنا ورعايتنا."},{text:"أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ",surah:"الزمر",number:36,tafsir:"أليس الله بكافٍ عبده محمداً في كل ما يهمه من أمور الدنيا والآخرة؟"},{text:"وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ",surah:"الأنفال",number:33,tafsir:"وما كان الله ليعذب هؤلاء المشركين وأنت يا محمد مقيم بين أظهرهم."},{text:"إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ",surah:"الرعد",number:11,tafsir:"إن الله لا يسلب قوماً نعمة أنعم بها عليهم حتى يغيروا ما هم عليه من طاعة وصلاح."},{text:"وَاللَّهُ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ",surah:"البقرة",number:212,tafsir:"والله يعطي من يشاء من خلقه عطاءً واسعاً لا حدود له."},{text:"وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ ۚ إِنَّ اللَّهَ بَالِغُ أَمْرِهِ ۚ قَدْ جَعَلَ اللَّهُ لِكُلِّ شَيْءٍ قَدْرًا",surah:"الطلاق",number:3,tafsir:"ومن يعتمد على الله في أموره فهو كافيه ما أهمَّه. إن الله مُنْفِذ أمره، لا يفوته شيء، ولا يعجزه مطلوب، قد جعل الله لكل شيء وقتًا ينتهي إليه، ومقدارًا لا يتجاوزه."},{text:"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ",surah:"آل عمران",number:8,tafsir:"يقولون: ربنا لا تمل قلوبنا عن الحق بعد أن هديتنا إليه، وامنحنا من فضلك رحمة واسعة، إنك أنت المعطي الجزيل العطاء."},{text:"إِنَّ مَعَ الْعُسْرِ يُسْرًا",surah:"الشرح",number:6,tafsir:"إن مع الضيق والشدة فرجًا ومخرجًا."},{text:"وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا",surah:"الطور",number:48,tafsir:"واصبر -أيها الرسول- لقضاء ربك وأمره فيما حمَّلك من الرسالة، وفيما يلحقك من أذى قومك، فإنك بحفظنا وكلاءتنا."},{text:"قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا ۚ إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ",surah:"الزمر",number:53,tafsir:"قل -أيها الرسول- لعبادي الذين تمادوا في المعاصي: لا تيأسوا من رحمة الله؛ لكثرة ذنوبكم، إن الله يغفر الذنوب جميعًا لمن تاب، إنه هو الغفور لذنوب التائبين، الرحيم بهم."},{text:"وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ",surah:"غافر",number:60,tafsir:"وقال ربكم -أيها الناس-: اعبدوني وحدي وادعوني، أجب دعاءكم وأغفر لكم."},{text:"فَإِنَّ مَعَ الْعُسْرِ يُسْرًا",surah:"الشرح",number:5,tafsir:"فإن مع الضيق والشدة فرجًا ومخرجًا."},{text:"وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ",surah:"العنكبوت",number:69,tafsir:"والذين جاهدوا في سبيلنا، وصبروا على الأذى في ذات الله، لنوفقنهم لطرق الخير، وإن الله لمع المحسنين بعونه وتوفيقه."},{text:"لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا",surah:"البقرة",number:286,tafsir:"لا يكلف الله نفسًا من الأعمال إلا ما تطيقه."},{text:"أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ",surah:"الرعد",number:28,tafsir:"ألا بذكر الله وتسبيحه وثنائه تسكن القلوب وتستأنس."},{text:"وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا",surah:"الطلاق",number:2,tafsir:"ومن يخف الله فيعمل بطاعته، يجعل له مخرجًا من كل ضيق."},{text:"وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ",surah:"الطلاق",number:3,tafsir:"ويسوق إليه الرزق من جهة لا تخطر بباله."},{text:"فَاصْبِرْ صَبْرًا جَمِيلًا",surah:"المعارج",number:5,tafsir:"فاصبر -أيها الرسول- على أذى قومك صبرًا لا جزع فيه ولا شكوى."},{text:"إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ",surah:"إبراهيم",number:39,tafsir:"إن ربي لمجيب لمن دعاه."},{text:"وَمَا كَانَ رَبُّكَ نَسِيًّا",surah:"مريم",number:64,tafsir:"وما كان ربك تاركًا لك ولا غافلاً عنك."},{text:"فَاسْتَجَبْنَا لَهُ وَنَجَّيْنَاهُ مِنَ الْغَمِّ ۚ وَكَذَٰلِكَ نُنجِي الْمُؤْمِنِينَ",surah:"الأنبياء",number:88,tafsir:"فأجبنا دعاءه، وخلصناه من كرب الشدة، وكما نجينا يونس ننجي المؤمنين المخلصين."},{text:"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ",surah:"الضحى",number:5,tafsir:"ولسوف يعطيك ربك -أيها الرسول- من الشفاعة في أمتك والخير الكثير حتى ترضى."},{text:"أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ",surah:"الزمر",number:36,tafsir:"أليس الله بكافٍ عبده محمدًا صلى الله عليه وسلم ما أهمَّه من أمر دينه ودنياه؟"},{text:"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ",surah:"البقرة",number:186,tafsir:"وإذا سألك -أيها النبي- عبادي عني فقل لهم: إني قريب منهم، أسمع دعاءهم وأجيبهم."},{text:"إِنَّ اللَّهَ مَعَ الصَّابِرِينَ",surah:"البقرة",number:153,tafsir:"إن الله مع الصابرين بعونه وتوفيقه وحفظه."},{text:"وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ",surah:"هود",number:88,tafsir:"وما توفيقي في إصابة الحق إلا بالله، عليه اعتمدت في أموري، وإليه أرجع بالتوبة."},{text:"لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا",surah:"التوبة",number:40,tafsir:"لا تحزن إن الله معنا بنصره وتأييده."},{text:"وَمَا ذَٰلِكَ عَلَى اللَّهِ بِعَزِيزٍ",surah:"إبراهيم",number:20,tafsir:"وما إهلاككم والإتيان بغيركم بممتنع على الله."},{text:"وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ",surah:"يوسف",number:21,tafsir:"والله مستولٍ على أمره، لا يغلبه أحد، ولكن أكثر الناس لا يعلمون حكمته في خلقه."},{text:"إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ",surah:"الأعراف",number:56,tafsir:"إن رحمة الله قريب من الذين يحسنون عبادته ويحسنون إلى خلقه."},{text:"وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ",surah:"المائدة",number:120,tafsir:"وهو سبحانه على كل شيء قدير، لا يعجزه شيء."},{text:"وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقْتَدِرًا",surah:"الكهف",number:45,tafsir:"وكان الله على كل شيء مقتدرًا، لا يعجزه شيء."},{text:"فَسَيَكْفِيكَهُمُ اللَّهُ ۚ وَهُوَ السَّمِيعُ الْعَلِيمُ",surah:"البقرة",number:137,tafsir:"فسيكفيك الله -أيها الرسول- شرهم وأذاهم، وهو السميع لأقوالكم، العليم بأحوالكم."},{text:"إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ",surah:"آل عمران",number:9,tafsir:"إن الله لا يخلف ما وعد به."},{text:"وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ",surah:"البقرة",number:216,tafsir:"والله يعلم ما هو خير لكم، وأنتم لا تعلمون ذلك."},{text:"وَمَن يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا",surah:"طه",number:112,tafsir:"ومن يعمل من الأعمال الصالحة وهو مؤمن بالله، فلا يخاف ظلمًا بزيادة سيئاته، ولا نقصًا من ثواب حسناته."},{text:"وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْرًا",surah:"الطلاق",number:4,tafsir:"ومن يخف الله فيعمل بطاعته، يسهل له أموره."},{text:"سَيَجْعَلُ اللَّهُ بَعْدَ عُسْرٍ يُسْرًا",surah:"الطلاق",number:7,tafsir:"سيجعل الله بعد ضيق وشدة سعة وفرجًا."},{text:"وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِن شَيْءٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ",surah:"فاطر",number:44,tafsir:"وما كان الله ليفوته شيء في السموات ولا في الأرض."},{text:"إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَّحِيمٌ",surah:"البقرة",number:143,tafsir:"إن الله بالناس لرحيم، يرحمهم ويشفق عليهم."},{text:"وَاصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ",surah:"هود",number:115,tafsir:"واصبر -أيها الرسول- على ما تلقى، فإن الله لا يضيع ثواب المحسنين في أعمالهم."},{text:"إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ",surah:"آل عمران",number:159,tafsir:"إن الله يحب الذين يعتمدون عليه في أمورهم."},{text:"وَاللَّهُ مَعَ الصَّابِرِينَ",surah:"الأنفال",number:66,tafsir:"والله مع الصابرين بعونه وتأييده."},{text:"فَإِنَّ حَسْبَكَ اللَّهُ",surah:"الأنفال",number:62,tafsir:"فإن الله كافيك وناصرك."},{text:"وَكَفَىٰ بِاللَّهِ وَكِيلًا",surah:"النساء",number:81,tafsir:"وكفى بالله حفيظًا وموفقًا لمن توكل عليه."}];export{r as d};
